-- ================= VDI-3477-01 — Anmeldung, Anwendungsbereich und Eignungspruefung (3 fields) =================
-- anlagenart — Anlagenart / Branche
update public.fields set verification_status='verified_against_standard', verification_quote='Biofilter werden erfolgreich an den in Tabelle 1 aufgeführten Anlagen eingesetzt (siehe VDI 2590 und [1 bis 4]). Die Tabelle erhebt bezüglich der dort jeweils aufgeführten Komponenten keinen Anspruch auf Vollständigkeit. | Tabelle 1. Anlagenarten, bei denen sich Biofilter zur Abgasreinigung bewährt haben — printed p.3, p.4', verification_note='md-verified 2026-09-05 (§1, Tab.1, printed p.3, p.4) [VC] — Enum-Granularitaet: die 6 kodierten Werte bilden die 5 gedruckten Gruppenzeilen der Tab.1 ab; "tierhaltung" ist in Tab.1 eine ZEILE unter "Nahrungs- und Genussmittelproduktion", als eigene Klasse gestuetzt auf Abschn. 6.5.3.2 (printed p.50)', verified_at=now() where id='4e4e6baf-c899-4f9b-b540-2e3085c3e804' and verification_status not in ('verified_against_standard','corrected');
-- biofilter_grundsaetzlich_geeignet — Biofiltration grundsaetzlich geeignet
update public.fields set verification_status='verified_against_standard', verification_quote='Die biologische Reinigung von Abgasen durch Biofilter kann dort angewendet werden, wo luftverunreinigende Stoffe vorliegen, die biologisch hinreichend schnell abbaubar sind. Der Schadstoffabbau erfolgt durch Mikroorganismen, die auf einem festen Träger angesiedelt sind. — printed p.14', verification_note='md-verified 2026-09-05 (§4.1, printed p.14) [VC] — Modal ist "kann" (Anwendbarkeitsaussage), keine "muss"-Pflicht', verified_at=now() where id='ddb7ca01-ac29-4d10-9c97-bb40fa35b2e6' and verification_status not in ('verified_against_standard','corrected');
-- pilotversuch_erforderlich — Pilotversuch erforderlich
update public.fields set verification_status='verified_against_standard', verification_quote='Trotz der zahlreichen praktischen Anwendungsfälle von Biofiltern sollte der Biofiltereinsatz auch künftig in Fällen, in denen bisher keine übertragbare Erfahrung vorliegt, durch Versuche überprüft werden. | Bei Rohgasströmen mit schwankender Konzentration und wechselnder Zusammensetzung kann die Austrittskonzentration höher sein als die Eingangskonzentration an Geruchsstoffen (negativer Wirkungsgrad). Durch langfristige Pilotversuche (mindestens drei Monate) muss die Eignung von Biofiltern getestet werden. — printed p.3, p.79', verification_note='md-verified 2026-09-05 (§1, §7.4, printed p.3, p.79) [VC]', verified_at=now() where id='745246d5-26a4-4901-a8f8-413925cb64cb' and verification_status not in ('verified_against_standard','corrected');

