-- e_E — Effektive Porositaet
update public.fields set verification_status='verified_against_standard', verification_quote='Aus diesem Grund ist hier die sogenannte effektive Porosität $e_{\mathrm{E}}$ zu betrachten, die die tatsächlich für die Strömung zur Verfügung stehenden Hohlräume beschreibt | Für vollkommen trockenes Material ( $V_{\mathrm{W}}=0$ ) werden $e$ und $e_{\mathrm{E}}$ identisch. Da sich jedoch die optimalen Feuchtegehalte für Biofiltermaterialien im Bereich von ca. $50 \%$ bis $60 \%$ bewegen, ist die effektive Porosität deutlich kleiner als die mit trockenen Materialien bestimmte. — printed p.26', verification_note='md-verified 2026-09-05 (§5.1.6.2 (Gl.10), printed p.26) [VC]', verified_at=now() where id='7e2c5073-9bde-48ee-9cc8-c48da4acf057' and verification_status not in ('verified_against_standard','corrected');
