-- materialart — Filtermaterialart
update public.fields set verification_status='verified_against_standard', verification_quote='Als Trägermaterial dienen meist organische Materialien, z.B., Holz- und Rindenhäcksel, Wurzelholz, Komposte aus Bioabfall, Baumrinden oder Komposte sonstigen Ursprungs, Fasertorf und Heidekraut sowie deren Mischungen untereinander oder mit sonstigen strukturierenden Materialien (siehe Tabelle 3 in Abschnitt 5.1.1). Es werden jedoch auch anorganische Materialien mit großer innerer Oberfläche und entsprechendem Mikroorganismenbesatz (Lava, Blähton) verwendet. — printed p.15', verification_note='md-verified 2026-09-05 (§4.1, Tab.3, printed p.15) [VC] — Enum-Granularitaet: Tab.3 fuehrt 11 Materialien (u.a. Siebueberlauf der Gruengutkompostierung, Blaehton, Polystyrolschaum/Kompost); die 9 kodierten Werte fassen diese zusammen', verified_at=now() where id='409d9e27-d201-43c5-9e29-dd827b2336ed' and verification_status not in ('verified_against_standard','corrected');
-- h — Filterhoehe (Schuetthoehe)
