update public.fields set verification_status='verified_against_standard', verification_quote='Für fast alle Anwendungsfälle ist es notwendig, das Abgas zu befeuchten. Die relative Feuchte muss dabei über $95 \%$ liegen und kann nur bei Befeuchtern mit entsprechend angeordneten Düsenebenen (einschließlich geeigneten Gleichrichtern) erreicht werden, die gleichzeitig mit und gegen den Luftstrom gerichtet sind. — printed p.35', verification_note='md-verified 2026-09-05 (§6.2.2.1, printed p.35) [VC] — Abschn. 5.1.4 (printed p.23) formuliert dieselbe Anforderung als "mindestens 95 % Saettigung" (also inklusiv); massgeblich fuer den Befeuchteraustritt ist die strikte Form "ueber 95 %" aus Abschn. 6.2.2.1', verified_at=now() where id='08afd1e6-b1e1-4ffa-bfc4-52e583220fe9' and verification_status not in ('verified_against_standard','corrected');
-- wasser_luft_zahl — Wasser-Luft-Zahl
