-- pH_filtermaterial — pH-Wert des Filtermaterials
update public.fields set verification_status='verified_against_standard', verification_quote='Beim Abbau organischer Kohlenstoffverbindungen stellt sich in der Regel ein neutraler bis schwach saurer pH -Wert ein. In einer Schwankungsbreite von 5,5 bis 7,5 ist der pH -Wert tolerabel. Schnelle und starke Schwankungen sind zu vermeiden und müssen gegebenenfalls mit Kalk gepuffert werden. In besonderen Einzelfällen, z.B., beim Abbau von Schwefelwasserstoff, kann der pH-Wert aber bewusst deutlich sauer sein. — printed p.84', verification_note='md-verified 2026-09-05 (§8.4, printed p.84) [VC]', verified_at=now() where id='369de50a-b744-4015-ba81-2359638341b1' and verification_status not in ('verified_against_standard','corrected');
-- CNP_verhaeltnis — C:N:P-Verhaeltnis
update public.fields set verification_status='verified_against_standard', verification_quote='Im Allgemeinen betragen die Stoffmengenverhältnisse zwischen $\mathrm{C}, \mathrm{N}$ und P etwa 100:5:1. Aus dem C-Gehalt der abzubauenden Schadstoffe ergibt sich die benötigte Menge N und P (siehe Abschnitt 4.2 und Abschnitt 5.1.3). — printed p.71', verification_note='md-verified 2026-09-05 (§7.3.2.3, printed p.71) [VC]', verified_at=now() where id='84e7ebd6-af83-4f4d-bbee-53f78008b5e3' and verification_status not in ('verified_against_standard','corrected');
-- naehrsalzzugabe_erfolgt — Naehrsalzzugabe erfolgt
update public.fields set verification_status='verified_against_standard', verification_quote='Besonders bei der Reinigung von Abgas aus Gießereien, Lackherstellung und Lackieranlagen ist eine häufige Nährstoffversorgung notwendig. — printed p.71', verification_note='md-verified 2026-09-05 (§7.3.2.3, printed p.71) [VC]', verified_at=now() where id='f2541b7d-31be-4b4a-b805-a40f35034cb0' and verification_status not in ('verified_against_standard','corrected');
-- instandhaltungsnachweis — Instandhaltungsnachweis gefuehrt
