-- ================= equations — QUOTE BACKFILL (status untouched; guard: verification_quote is null) =================
-- Gl.(10)  e_E = (V_H - V_W) / V_G
update public.equations set verification_quote='Aus diesem Grund ist hier die sogenannte effektive Porosität $e_{\mathrm{E}}$ zu betrachten, die die tatsächlich für die Strömung zur Verfügung stehenden Hohlräume beschreibt | e_{\mathrm{E}}=\frac{V_{\mathrm{H}}-V_{\mathrm{W}}}{V_{\mathrm{G}}} \tag{10} — printed p.26', verification_note='md-verified 2026-09-05 (§5.1.6.2, printed p.26) [VC]', verified_at=now() where id='757d09cf-e1e9-46db-b71d-1d4324e43939' and verification_quote is null;
-- Gl.(9)  e = V_H / V_G
update public.equations set verification_quote='Diese Größe ist definiert als das dimensionslose Verhältnis von Hohlraumvolumen $V_{\mathrm{H}}$ zu Gesamtvolumen $V_{\mathrm{G}}$ | e=\frac{V_{\mathrm{H}}}{V_{\mathrm{G}}} \tag{9} — printed p.26', verification_note='md-verified 2026-09-05 (§5.1.6.2, printed p.26) [VC]', verified_at=now() where id='a0214894-a607-417e-a8c5-69432ab7508e' and verification_quote is null;
-- Gl.(11)  w_P = V_dot / (A * e_E)
update public.equations set verification_quote='Daher wird die tatsächliche Strömungsgeschwindigkeit $w_{\mathrm{P}}$ in den Kanälen mit folgender Gleichung beschrieben | w_{\mathrm{P}}=\frac{\dot{V}}{A \cdot E_{\mathrm{E}}}=\frac{w}{e_{\mathrm{E}}} \tag{11} — printed p.27', verification_note='md-verified 2026-09-05 (§5.1.6.2, printed p.27) [VC] — md druckt im Nenner ein grosses E_E statt e_E - mathpix/Druck-Variante, inhaltlich die effektive Porositaet', verified_at=now() where id='c133dd5e-65c2-488d-9eab-130075085a9a' and verification_quote is null;
-- Gl.(12)  V_dot = (d_P^2 * dp) / (32 * nu * rho * l) * A_P
update public.equations set verification_quote='Aus Gleichung (12) erhält man den Gesamtvolumenstrom über die Filterfläche | \dot{V}=w_{\mathrm{P}}=A_{\mathrm{P}}=\frac{d_{\mathrm{P}}^{2} \cdot \Delta p}{32 \cdot v \cdot \rho \cdot l} \cdot A_{\mathrm{P}} \tag{12} — printed p.27', verification_note='md-verified 2026-09-05 (§5.1.6.3, printed p.27) [VC] — Quote verbatim INKL. md-OCR-Defekt (Gleichheitszeichen statt Produkt zwischen w_P und A_P); die kodierte Formel nutzt das Produkt. PDF schlaegt md (SR-3)', verified_at=now() where id='a9d239d9-e1e7-43f7-ac38-fb19dfa71106' and verification_quote is null;
-- Gl.(13)  w = V_dot / A
update public.equations set verification_quote='Dies führt zu der spezifischen Filterflächenbelastung (Anströmgeschwindigkeit in $\mathrm{m} / \mathrm{s}$ ) | w=\frac{\dot{V}}{A}=w_{\mathrm{P}} \cdot \frac{A_{\mathrm{P}}}{A}=\frac{d_{\mathrm{P}}^{2} \cdot \Delta p}{32 \cdot v \cdot \rho \cdot l} \cdot \frac{A_{\mathrm{P}}}{A} \tag{13} — printed p.27', verification_note='md-verified 2026-09-05 (§5.1.6.3, printed p.27) [VC]', verified_at=now() where id='00929d47-c8bb-4b77-ba25-906ad3d1587d' and verification_quote is null;
-- Gl.(6)  p_e / p_0 <= 0,95
update public.equations set verification_quote='Außerdem wird angenommen, dass die in der Biofilterschüttung strömende Luft inkompressibel ist. | p_{\mathrm{e}} / p_{0} \leq 0,95 \tag{6} — printed p.25', verification_note='md-verified 2026-09-05 (§5.1.6.1, printed p.25) [VC]', verified_at=now() where id='752c86b8-4f81-434a-a689-e1f905c1bfc6' and verification_quote is null;
-- Gl.(7)  V_dot_cont = w * A
update public.equations set verification_quote='Mit der Annahme der Inkompressibilität ergibt sich aus der Kontinuitätsgleichung ein wichtiger Zusammenhang für die Berechnung der Strömungsgeschwindigkeit und damit der Aufenthaltszeit | w \cdot A=\text { const. }=\dot{V} \tag{7} — printed p.25', verification_note='md-verified 2026-09-05 (§5.1.6.2, printed p.25) [VC]', verified_at=now() where id='4c52eb26-2a4e-4797-81fa-726c91687b2a' and verification_quote is null;
-- Gl.(8)  vel_ratio = A_2 / A_1
update public.equations set verification_quote='Folglich verhalten sich die Geschwindigkeiten längs der Strömung eines inkompressiblen Fluids unter der Annahme stationärer Strömung umgekehrt wie die durchströmten Flächen | W_{1} / W_{2}=A_{2} / A_{1} \tag{8} — printed p.26', verification_note='md-verified 2026-09-05 (§5.1.6.2, printed p.26) [VC]', verified_at=now() where id='b92ccebf-6d79-4474-b09e-f6e62f8d8340' and verification_quote is null;
-- Gl.(A1)  M_S = V_dot * c_A
update public.equations set verification_quote='Aus obigen Angaben ergibt sich eine Schadstofffracht von | $\dot{M}_{\mathrm{s}}=\dot{V} \cdot c_{2}=10000 \mathrm{~m}^{3} / \mathrm{h} \cdot 0,8 \mathrm{~g} / \mathrm{m}^{3}=8000 \mathrm{~g} / \mathrm{h}$ — printed p.89', verification_note='md-verified 2026-09-05 (Anhang A, printed p.89) [VC] — Anhang-A-Rechenbeispiel; die Zahlenwerte sind Beispielwerte, die Rechenvorschrift M_S = V mal c ist normativ', verified_at=now() where id='3f58e084-5bc5-4522-9038-631da022284a' and verification_quote is null;
-- Gl.(A2)  V_F = M_S / m_S
update public.equations set verification_quote='Mit der im Vorversuch ermittelten möglichen spezifischen Filtervolumenbelastung von $60 \mathrm{~g} /\left(\mathrm{m}^{3} \cdot \mathrm{~h}\right)$ ergibt sich das notwendige Filtervolumen zu | V_{\mathrm{F}}=\frac{\dot{M}_{\mathrm{s}}}{\dot{m}_{\mathrm{S}}}=\frac{8000 \mathrm{~g} / \mathrm{h}}{60 \mathrm{~g} /\left(\mathrm{m}^{3} \cdot \mathrm{~h}\right)}=133 \mathrm{~m}^{3} — printed p.89', verification_note='md-verified 2026-09-05 (Anhang A, printed p.89) [VC] — Anhang-A-Rechenbeispiel; 60 g/(m³·h) ist ein Versuchswert, keine normative Vorgabe', verified_at=now() where id='0158fa88-a63c-447a-80af-04519cc061e0' and verification_quote is null;
-- Gl.(4)  U = p_D / p_DS
update public.equations set verification_quote='Verhältnis von Wasserdampfpartialdruck und Sättigungsdampfdruck bei gegebener Temperatur | U=\left.\frac{p_{\mathrm{D}}}{p_{\mathrm{DS}}}\right|_{T} \tag{4} — printed p.11', verification_note='md-verified 2026-09-05 (§2, printed p.11) [VC]', verified_at=now() where id='d895f9ed-5a4a-434f-bdf2-19c2c127b427' and verification_quote is null;
-- Gl.(1)  eta_G = (q_G_roh - q_G_rein) / q_G_roh
update public.equations set verification_quote='technischer Wirkungsgrad, der die Minderung des emittierten Geruchsstoffstroms $q_{\mathrm{G}}$ beschreibt | \eta_{\mathrm{G}}=\frac{q_{\mathrm{G}, \text { roh }}-q_{\mathrm{G}, \text { rein }}}{q_{\mathrm{G}, \text { roh }}} \tag{1} — printed p.10', verification_note='md-verified 2026-09-05 (§2, printed p.10) [VC]', verified_at=now() where id='654425ed-d005-44c9-869e-7943e9e304db' and verification_quote is null;
-- Gl.(2)  eta_G = (c_G_roh - c_G_rein) / c_G_roh
update public.equations set verification_quote='Anmerkung 1: Unter der Voraussetzung, dass der Volumenstrom des Abgases durch das Emissionsminderungsverfahren nicht oder nur vernachlässigbar verändert wird, kann der Geruchsstoffminderungsgrad auch aus den entsprechenden → Geruchsstoffkonzentrationen berechnet werden | \eta_{\mathrm{G}}=\frac{q_{\mathrm{G}, \text { roh }}-q_{\mathrm{G}, \text { rein }}}{q_{\mathrm{G}, \text { roh }}} \tag{2} — printed p.10', verification_note='md-verified 2026-09-05 (§2, printed p.10) [VC] — Quote verbatim: die Richtlinie druckt Gl.(2) identisch zu Gl.(1) in der q_G-Form. Die Kodierung nutzt die c_G-Form gemaess Anmerkung 1 - bekannter Druckfehler, VA-Pass erforderlich', verified_at=now() where id='60377b26-5754-46e8-a0c2-7a7a4cad4a81' and verification_quote is null;
-- Gl.(5)  eta = (c_roh - c_rein) / c_roh
update public.equations set verification_quote='Differenz der Konzentration eines oder mehrerer definierter Abgasinhaltsstoffe vor und nach dem Filter bei stoffspezifischen Messungen, bezogen auf die Konzentration des Stoffs/der Stoffe im Rohgas | \eta=\frac{C_{\mathrm{roh}}-C_{\mathrm{rein}}}{C_{\mathrm{roh}}} \tag{5} — printed p.12', verification_note='md-verified 2026-09-05 (§2, printed p.12) [VC]', verified_at=now() where id='8d63c71a-d6c4-4559-bfc8-79c9038048d6' and verification_quote is null;
-- Gl.(B2)  Z = (V_P_dot + V_N_dot) / V_P_dot
update public.equations set verification_quote='Die am Olfaktometer eingestellten Verdünnungszahlen werden wie folgt bestimmt | Z=\frac{\dot{V}_{\mathrm{P}}+\dot{V}_{\mathrm{N}}}{\dot{V}_{\mathrm{P}}}=1+\frac{\dot{V}_{\mathrm{N}}}{\dot{V}_{\mathrm{P}}} \tag{B2} — printed p.91', verification_note='md-verified 2026-09-05 (Anhang B, printed p.91) [VC]', verified_at=now() where id='a4766b6c-13f6-49f5-8a61-c186f18d6cb7' and verification_quote is null;
-- Gl.(B4)  P_G = 10 * lg(Z)
update public.equations set verification_quote='Tabelle B1. Beispiel für eine mögliche Verdünnungsreihe am Olfaktometer (Stufensprung Faktor 2) | \hline Geruchspegel $P$ in $\mathrm{dB}_{\mathrm{od}}(10 \mathrm{lg} Z)$ & 38,8 & 41,8 & 44,8 & 47,8 & 50,8 & 53,8 \\ — printed p.92', verification_note='md-verified 2026-09-05 (Anhang B (Tab.B1), printed p.92) [VC] — P_G = 10 lg Z ist als Spaltendefinition der Tab.B1 gedruckt, nicht als nummerierte Gleichung', verified_at=now() where id='00d2ea9b-4237-4c17-8f1a-04a865f44563' and verification_quote is null;

-- ================= equations — status upgrade (verified_via_cross_reference -> verified_against_standard) =================
-- Both are printed IN VDI 3477 itself (Anhang B), so "against standard" is the correct status.
-- Gl.(B1)  I = k_W * lg(c / c_0)   (was: verified_via_cross_reference)
update public.equations set verification_status='verified_against_standard', verification_quote='Die mathematische Basis des Darbietungsmodus der definierten Verdünnungen von Geruchsstoffprobe und Neutralluft am Olfaktometer ist die Weber-Fech-ner-Gleichung, die die Beziehung zwischen Reizstärke $c_{\mathrm{G}}$ (Konzentration) und Empfindungsstärke $I$ (Intensität) beschreibt | I=k_{\mathrm{W}} \cdot \lg \left(c / c_{0}\right) \tag{B1} — printed p.90', verification_note='md-verified 2026-09-05 (Anhang B, printed p.90) [VC]', verified_at=now() where id='4a29668f-fe30-484e-bc31-1690a5222e81' and verification_status <> 'verified_against_standard';
-- Gl.(B3)  Z_50 = max(c_G, -c_G)   (was: verified_via_cross_reference)
update public.equations set verification_status='verified_against_standard', verification_quote='wählte man per Konvention diejenige Verdünnungszahl als Maß für die „geruchsinduzierende“ Konzentration $c_{\mathrm{G}}$ des untersuchten Gases in $\mathrm{GE}_{\mathrm{E}} / \mathrm{m}^{3}$, bei der in $50 \%$ der Darbietungen am Olfaktometer (nicht bei $50 \%$ der Prüfer!) gerade eben ein Geruch am Olfaktometerausgang wahrgenommen wird | Z_{50}=\left|c_{\mathrm{G}}\right| \tag{B3} — printed p.91', verification_note='md-verified 2026-09-05 (Anhang B, printed p.91) [VC]', verified_at=now() where id='9abe6eac-0d0c-4dcd-9948-93faf27793b4' and verification_status <> 'verified_against_standard';
